def normal(c):return not c['inactive'] and any(x.isalpha()for x in c['text']) and c['tag'].lower() not in ['text','tspan']
def failures(dataset):return [dict(route=r['pattern'],viewport=v,**c)for r in dataset['routes']for v in ['desktop','mobile']for c in r.get(v,{}).get('checks',[]) if normal(c) and not c['passes']]
oldfails=failures(before);newfails=failures(after)
limitations=['One baseline dark mobile graph image contains a resize/sticky-header capture artifact; its pixel comparison is inconclusive. Final graph appearance and unchanged dark role values were reviewed separately.', 'Dark Server Management full-page heights differ with dynamic diagnostics; those images are not asserted pixel-identical. Other representative dark captures are identical or near-identical in the recorded thresholded comparison.', 'Automated initial-state capture/contrast sampling spans all 100 route templates; 3 redirect aliases are partial, not interior sign-off. Human visual review focuses on representative modules and overview sheets.','Default text scan is bounded to 550 direct-text elements per page; SVG fill, native widgets, group opacity and gradients need separate validation. Disabled controls and color emoji are excluded from normal text assertions.','Eight representative dark route templates plus 40 conditional/component state captures across both themes; not every dark workflow was recaptured. Existing dark token values are regression-checked.','Static deployment/chart/control fixtures render actual production components with fictional props; they do not run real deployment operations or provider calls.','No live-server changes, paid AI research, real notification delivery, native camera capture, hardware printing or screen-reader/Firefox/Safari certification.','Authentication screens were visually captured; password recovery, real 2FA login, invitation email and external provider workflows are not end-to-end verified.','Existing splash-page lint issue (plain internal anchor) and six image warnings predate this pass; no new lint errors in changed shared components.','Large production-sized collections and every possible tag icon combination were not exercised. Existing layout checks cover 12 definition cards and long cultivar names; all care/tag color families are measured.']
coverage={'sourceCommit':source,'routesDiscovered':len(routes),'routeStatusCounts':dict(collections.Counter(r['desktop']for r in routes)),'routes':routes,'componentSourceInventory':len(inventory['components']),'statesBefore':[{k:v for k,v in x.items()if k!='measurements'}for x in sb],'statesAfter':[{k:v for k,v in x.items()if k!='measurements'}for x in sa],'darkRoutesBefore':[{k:r.get(k)for k in ['pattern','desktopScreenshot','mobileScreenshot']}for r in db['routes']],'darkRoutesAfter':[{k:r.get(k)for k in ['pattern','desktopScreenshot','mobileScreenshot']}for r in da['routes']],'limitations':limitations}
